export type ExportFormat = "pdf" | "xlsx" | "csv";

const LABELS: Record<ExportFormat, { label: string; icon: string }> = {
    pdf: { label: "PDF", icon: "bi-filetype-pdf" },
    xlsx: { label: "Excel", icon: "bi-file-earmark-excel" },
    csv: { label: "CSV", icon: "bi-filetype-csv" },
};

/**
 * Export dropdown. Files are generated by the server from the same query/authorization as the screen (§39, §51);
 * URL shape: `${baseUrl}/${format}` + current query string (active filters), e.g. /reports/export/pdf?from=... Pass only formats the endpoint actually supports.
 */
export function ExportButton({ baseUrl, formats = ["pdf", "xlsx", "csv"], disabled = false }: {
    baseUrl: string; formats?: ExportFormat[]; disabled?: boolean;
}) {
    const href = (f: ExportFormat) => {
        const qs = window.location.search;
        return `${baseUrl.replace(/\/$/, "")}/${f}${qs}`;
    };
    return (
        <div className="dropdown">
            <button type="button" className="btn btn-outline-primary dropdown-toggle" style={{ minHeight: 48 }} data-bs-toggle="dropdown" aria-expanded="false" disabled={disabled}>
                <i className="bi bi-download me-1" aria-hidden="true" />تصدير
            </button>
            <ul className="dropdown-menu dropdown-menu-end">
                {formats.map((f) => (
                    <li key={f}>
                        <a className="dropdown-item py-2" href={href(f)} download>
                            <i className={`bi ${LABELS[f].icon} me-2`} aria-hidden="true" />{LABELS[f].label}
                        </a>
                    </li>
                ))}
            </ul>
        </div>
    );
}